styles.css:
@import url('https://fonts.googleapis.com/css2?family=Poppins:ital,wght@0,300;0,400;0,500;0,600;0,700;1,300;1,400&display=swap');

/* ========================================
   GLOBAL TYPOGRAPHY
   ======================================== */

.wp-site-blocks {
  --wp--preset--font-family--heading: 'Poppins', sans-serif;
  --wp--preset--font-family--body: 'Poppins', sans-serif;
  font-family: 'Poppins', sans-serif !important;
  font-weight: 400;
  background: #101010;
  color: #fff;
}

.wp-site-blocks :is(
  h1, h2, h3, h4, h5, h6,
  .wp-block-post-title,
  .bh-brand
) {
  font-family: 'Poppins', sans-serif !important;
  font-weight: 500 !important;
  letter-spacing: normal !important;
  text-transform: none !important;
}

.wp-site-blocks :is(
  p, li, .wp-block-navigation,
  button, .wp-element-button
) {
  font-family: 'Poppins', sans-serif;
}

.wp-site-blocks .bh-section h2 {
  font-size: clamp(28px, 3vw, 44px);
  line-height: 1.25;
}

/* ========================================
   HEADER
   ======================================== */

.bh-header {
  gap: 24px;
  flex-wrap: nowrap !important;
}

.bh-header > .wp-block-group {
  min-width: 0;
  flex: 1;
}

.bh-header .wp-block-site-title {
  min-width: 0;
  overflow-wrap: anywhere;
  font-size: clamp(18px, 2vw, 26px);
}

.bh-header .wp-block-site-logo,
.bh-header .wp-block-navigation {
  flex-shrink: 0;
}

.wp-site-blocks .bh-header .wp-block-navigation {
  font-size: 14px;
  font-weight: 400;
}

.bh-header .wp-block-navigation__responsive-container-open {
  min-width: 44px;
  min-height: 44px;
  align-items: center;
  justify-content: center;
}

@media (min-width: 1101px) {
  .wp-site-blocks .bh-header .wp-block-navigation__container {
    gap: clamp(18px, 3vw, 56px);
  }
}

@media (max-width: 1100px) {
  .bh-header .wp-block-navigation__responsive-container-open:not(.always-shown) {
    display: flex;
  }

  .bh-header .wp-block-navigation__responsive-container:not(.is-menu-open) {
    display: none !important;
  }
}

/* MOBILE MENU */

.bh-header .wp-block-navigation__responsive-container.is-menu-open {
  background: #101010 !important;
  color: #fff !important;
  padding: 80px 24px 32px !important;
  overflow-y: auto;
}

.bh-header .is-menu-open .wp-block-navigation__responsive-container-content {
  align-items: stretch !important;
  padding-top: 0 !important;
}

.bh-header .is-menu-open .wp-block-navigation__container {
  width: 100%;
  align-items: stretch !important;
  gap: 8px !important;
}

.bh-header .is-menu-open .wp-block-navigation-item {
  width: 100%;
  align-items: flex-start !important;
}

.bh-header .is-menu-open .wp-block-navigation-item__content {
  display: block;
  padding: 10px 0;
  font-size: 18px;
  line-height: 1.4;
  text-align: left;
  color: inherit;
}

.bh-header .is-menu-open .wp-block-navigation__submenu-container {
  position: static !important;
  width: 100%;
  min-width: 0 !important;
  background: transparent !important;
  border: 0 !important;
  padding: 0 0 8px 18px !important;
  gap: 0 !important;
}

.bh-header .is-menu-open .wp-block-navigation__submenu-container
.wp-block-navigation-item__content {
  font-size: 15px;
  color: #b4bdc7;
  padding: 8px 0;
}

.bh-header .is-menu-open .wp-block-navigation__responsive-container-close {
  position: fixed !important;
  top: 24px;
  right: 24px;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

body.admin-bar .bh-header .is-menu-open
.wp-block-navigation__responsive-container-close {
  top: 64px;
}

/* ========================================
   PRODUCTION PAGE
   ======================================== */

.wp-site-blocks .bh-project-layout {
  display: grid;
  max-width: 860px !important;
  margin-inline: auto;
  grid-template-columns: minmax(0, 386px) minmax(0, 1fr) !important;
  gap: 44px !important;
  align-items: start;
}

.wp-site-blocks .bh-project-poster {
  width: 100%;
  max-width: none;
}

.wp-site-blocks .bh-project-poster img {
  display: block;
  width: 100%;
  height: auto;
  max-height: none;
  object-fit: contain;
}

body .bh-project-layout h1,
body .bh-trailer h2 {
  font-family: 'Poppins', sans-serif !important;
  font-weight: 500 !important;
  letter-spacing: normal !important;
  text-transform: none !important;
}

.wp-site-blocks .bh-project-layout h1 {
  font-size: clamp(30px, 3.2vw, 48px) !important;
  line-height: 1.2 !important;
  margin: 12px 0 24px !important;
  overflow-wrap: anywhere;
}

body .bh-project-layout .bh-eyebrow {
  display: none !important;
}

.wp-site-blocks .bh-project-copy {
  font-size: 18px;
  overflow-wrap: anywhere;
}

body .bh-project-copy,
body .bh-project-copy p,
body .bh-project-copy li {
  font-family: 'Poppins', sans-serif !important;
  font-weight: 300 !important;
  line-height: 1.6 !important;
}

.wp-site-blocks .bh-project-copy p {
  margin-block: 0 28px;
}

/* TRAILER */

.wp-site-blocks .bh-trailer {
  max-width: 930px;
  margin: 76px auto 0;
}

.wp-site-blocks .bh-trailer h2 {
  font-size: clamp(28px, 3.2vw, 46px) !important;
  line-height: 1.2 !important;
  text-align: center;
  margin: 0 0 30px;
}

.wp-site-blocks .bh-trailer .bh-video {
  max-width: 930px;
  margin: 0 auto;
}

.bh-video iframe {
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  height: auto;
  border: 0;
  background: #171d23;
}

/* ========================================
   GENERAL CONTENT AND LEGAL PAGES
   ======================================== */

.wp-site-blocks .bh-prose {
  max-width: 960px !important;
  margin-inline: auto;
}

.wp-site-blocks .bh-prose h1 {
  font-size: clamp(32px, 4vw, 52px) !important;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.bh-prose .wp-block-post-content {
  line-height: 1.75;
  overflow-wrap: anywhere;
}

.wp-site-blocks .bh-prose .wp-block-post-content h2 {
  font-size: clamp(27px, 3vw, 38px);
  line-height: 1.25;
  margin-top: 1.5em;
}

.wp-site-blocks .bh-prose .wp-block-post-content h3 {
  font-size: clamp(23px, 2.5vw, 30px);
  line-height: 1.3;
}

.bh-prose .wp-block-post-content :is(img, video) {
  max-width: 100%;
  height: auto;
}

.bh-prose .wp-block-post-content iframe {
  max-width: 100%;
}

/* ========================================
   BLOG / NEWS LISTING
   ======================================== */

.wp-site-blocks .bh-news {
  max-width: 1280px !important;
  margin-inline: auto;
}

.wp-site-blocks .bh-news h1 {
  font-size: clamp(38px, 5vw, 64px);
  line-height: 1.15;
  margin: 16px 0;
}

.bh-news-intro {
  color: #b4bdc7;
  max-width: 600px;
  margin-left: 0 !important;
  margin-right: auto !important;
  margin-bottom: 40px;
}

.bh-news .wp-block-post-template {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 28px;
}

.bh-news .wp-block-post {
  min-width: 0;
  background: #171d23;
  border: 1px solid #39434e;
  padding: 0 24px 24px;
  border-radius: 8px;
  overflow: hidden;
}

.bh-news .wp-block-post-featured-image {
  margin: 0 -24px 24px;
}

.bh-news .wp-block-post-featured-image img {
  display: block;
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}

.wp-site-blocks .bh-news .wp-block-post-title {
  font-size: clamp(23px, 2vw, 28px);
  line-height: 1.25;
  margin: 16px 0;
  overflow-wrap: anywhere;
}

.bh-news .wp-block-post-title a {
  text-decoration: none;
}

.bh-news .wp-block-post-title a:hover {
  color: #65d5f0;
}

.bh-news .wp-block-post-excerpt {
  font-size: 15px;
  line-height: 1.7;
  color: #b4bdc7;
}

.bh-news .wp-block-post-excerpt__more-link {
  color: #65d5f0;
  display: inline-block;
  padding: 10px 0;
}

.bh-news .wp-block-query-pagination {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  margin-top: 36px;
}

.bh-news .wp-block-query-pagination a {
  display: inline-block;
  padding: 10px;
}

/* AUTHOR AND DATE */

.bh-story-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 20px;
  color: #b4bdc7;
  font-size: 13px;
  margin-block: 16px 24px;
}

.bh-story-meta > * {
  margin: 0 !important;
}

.bh-story-meta .wp-block-post-author-name::before {
  content: "By ";
}

.bh-news .wp-block-post-date,
.bh-news .wp-block-post-author-name {
  color: #b4bdc7;
  font-size: 13px;
}

/* INDIVIDUAL ARTICLE */

.wp-site-blocks .bh-article {
  max-width: 1000px !important;
  padding-top: 56px;
}

.bh-article-header {
  max-width: 800px;
  margin-inline: auto;
}

.wp-site-blocks .bh-article h1 {
  font-size: clamp(32px, 4vw, 52px) !important;
  line-height: 1.2;
  margin: 16px 0 24px;
}

.bh-article-image {
  margin: 32px 0 48px;
}

.bh-article-image img {
  display: block;
  width: 100%;
  object-fit: cover;
  border-radius: 8px;
}

.bh-article .wp-block-post-content {
  max-width: 740px;
  margin-inline: auto;
  font-size: 17px;
  line-height: 1.8;
  overflow-wrap: anywhere;
}

.bh-article .wp-block-post-content > * {
  max-width: 100%;
}

.bh-article .wp-block-post-content table {
  display: block;
  max-width: 100%;
  overflow-x: auto;
}

.bh-article .wp-block-post-content blockquote {
  border-left: 3px solid #65d5f0;
  margin-inline: 0;
  padding-left: 24px;
  color: #b4bdc7;
}

/* AUTHOR BIOGRAPHY */

.bh-author-bio {
  max-width: 740px;
  margin: 48px auto 0;
  padding: 28px;
  background: #171d23;
  border: 1px solid #39434e;
  border-radius: 8px;
}

.bh-author-bio .wp-block-post-author-name {
  font-size: 22px;
  margin: 12px 0;
}

.bh-author-bio .wp-block-post-author-biography {
  color: #b4bdc7;
  line-height: 1.7;
}

/* PREVIOUS / NEXT ARTICLE */

.bh-story-navigation {
  max-width: 740px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin: 32px auto 0;
  padding-top: 24px;
  border-top: 1px solid #39434e;
  overflow-wrap: anywhere;
}

.bh-story-navigation > * {
  margin: 0;
}

.bh-story-navigation .post-navigation-link-next {
  text-align: right;
}

/* ========================================
   HOMEPAGE
   ======================================== */

.wp-site-blocks .bh-home-refresh {
  max-width: none !important;
  background: #101010;
  color: #fff;
}

.bh-home-refresh > * {
  margin-block-start: 0;
}

/* VIDEO / IMAGE HERO */

.wp-site-blocks .bh-home-refresh .bh-home-video {
  width: 100%;
  max-width: none !important;
  padding: clamp(32px, 7vw, 110px);
  min-height: 640px;
}

.bh-home-video .wp-block-cover__inner-container {
  width: 100%;
  max-width: 1240px;
  margin-inline: auto;
}

.bh-home-video .wp-block-cover__video-background,
.bh-home-video .wp-block-cover__image-background {
  object-fit: cover;
  object-position: center;
}

.bh-home-hero-copy {
  max-width: 700px;
}

.wp-site-blocks .bh-home-refresh .bh-home-hero-copy h1 {
  font-family: 'Poppins', sans-serif !important;
  font-weight: 500 !important;
  line-height: 1.08 !important;
  letter-spacing: -0.025em !important;
  margin: 20px 0 28px;
}

.bh-home-hero-copy > p:not(.bh-eyebrow) {
  max-width: 580px;
  font-size: 17px;
  line-height: 1.75;
  margin-bottom: 28px;
}

.bh-home-refresh .bh-eyebrow {
  color: #65d5f0;
  font-size: 12px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.wp-site-blocks .bh-home-refresh h2 {
  font-family: 'Poppins', sans-serif !important;
  font-size: clamp(30px, 3.5vw, 48px);
  font-weight: 500 !important;
  line-height: 1.2;
}

/* PRODUCTION ROW SECTION */

.bh-home-productions {
  padding: 64px 0;
  overflow: hidden;
}

.bh-home-productions > p,
.bh-home-productions > h2 {
  text-align: center;
  padding-inline: 20px;
}

.bh-home-productions > .wp-block-buttons {
  padding-inline: 20px;
}

.bh-home-refresh .bh-marquee {
  padding: 24px 0 32px;
}

/* REMOVE PAUSE BUTTON ON HOMEPAGE */

.bh-home-refresh .bh-pause {
  display: none !important;
}

/* FASTER CONTINUOUS MOTION */

@keyframes bh-home-scroll {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

.bh-home-refresh .bh-track {
  display: flex;
  width: max-content;
  animation: bh-home-scroll 28s linear infinite !important;
  animation-play-state: running !important;
}

/* SECOND ROW MOVES THE OTHER WAY */

.bh-home-refresh .bh-reverse .bh-track {
  animation-direction: reverse !important;
}

/* KEEP MOVING ON HOVER AND FOCUS */

.bh-home-refresh .bh-row:hover .bh-track,
.bh-home-refresh .bh-row:focus-within .bh-track,
.bh-home-refresh .is-paused .bh-track {
  animation-play-state: running !important;
}

.bh-home-refresh .bh-row {
  overflow: hidden;
  margin-bottom: 28px;
}

.bh-home-refresh .bh-set {
  display: flex;
  gap: 20px;
  padding-right: 20px;
}

.bh-home-refresh .bh-card {
  width: 230px;
  flex: 0 0 230px;
}

.wp-site-blocks .bh-home-refresh .bh-card h3 {
  font-size: 18px;
  font-weight: 400 !important;
  line-height: 1.35;
}

.bh-home-refresh .bh-card p {
  font-size: 12px;
  color: #b4bdc7;
}

/* STUDIO INTRODUCTION */

.bh-home-intro {
  max-width: 1000px;
  margin-inline: auto;
  padding: 72px 28px;
}

.bh-home-intro > p:not(.bh-eyebrow) {
  max-width: 760px;
  font-size: 17px;
  line-height: 1.8;
  color: #d4d4d4;
}

.bh-home-intro .wp-block-buttons {
  margin-top: 28px;
}

/* CONTACT SECTION */

.bh-home-contact {
  padding: 72px 24px;
  background: #171d23;
  text-align: center;
}

.bh-home-contact p {
  color: #b4bdc7;
  margin-bottom: 28px;
}

.bh-home-refresh .wp-block-button__link {
  padding: 14px 24px;
  font-size: 14px;
  font-weight: 500;
  border-radius: 3px;
}

/* ========================================
   TABLET
   ======================================== */

@media (max-width: 1000px) {
  .bh-news .wp-block-post-template {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* ========================================
   MOBILE
   ======================================== */

@media (max-width: 700px) {
  .bh-header {
    padding: 16px 20px;
    gap: 16px !important;
  }

  .bh-header .bh-brand {
    font-size: 18px;
    line-height: 1.2;
  }

  .bh-section {
    padding: 36px 20px;
  }

  .wp-site-blocks .bh-project-layout {
    grid-template-columns: 1fr !important;
    gap: 28px !important;
  }

  .wp-site-blocks .bh-project-poster {
    width: min(100%, 386px);
    margin-inline: auto;
  }

  .wp-site-blocks .bh-project-copy {
    font-size: 16px;
  }

  .wp-site-blocks .bh-trailer {
    margin-top: 40px;
  }

  .wp-site-blocks .bh-home-refresh .bh-home-video {
    min-height: 560px !important;
    padding: 64px 24px;
  }

  .bh-home-hero-copy > p:not(.bh-eyebrow) {
    font-size: 16px;
    line-height: 1.65;
  }

  .bh-home-productions {
    padding: 40px 0;
  }

  .bh-home-refresh .bh-card {
    width: 170px;
    flex-basis: 170px;
  }

  .wp-site-blocks .bh-home-refresh .bh-card h3 {
    font-size: 16px;
  }

  .bh-home-intro,
  .bh-home-contact {
    padding: 48px 24px;
  }
}

@media (max-width: 600px) {
  .bh-news .wp-block-post-template {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .wp-site-blocks .bh-article {
    padding-top: 32px;
  }

  .bh-article .wp-block-post-content {
    font-size: 16px;
    line-height: 1.75;
  }

  .bh-article-image {
    margin: 24px 0 32px;
  }

  .bh-author-bio {
    padding: 20px;
  }

  .bh-story-navigation {
    grid-template-columns: 1fr;
  }

  .bh-story-navigation .post-navigation-link-next {
    text-align: left;
  }
}

/* ========================================
   REDUCED-MOTION PREFERENCE
   ======================================== */

@media (prefers-reduced-motion: reduce) {
  .bh-home-refresh .bh-track {
    animation: none !important;
  }

  .bh-home-refresh .bh-clone {
    display: none;
  }

  .bh-home-refresh .bh-row {
    overflow-x: auto;
  }
}
